/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CriticalCoinRewardInputs, CellsCardRewardInputs, criticalCoinExpectedBasePerBasicKill, cellsPerEliteAfterCard
 * depends    —
 * used by    src/calculators/specs.generated, src/mechanics/resource-drops/index, src/mechanics/resource-drops/types, src/mechanics/resource-drops/wave-drop-yield, src/mechanics/resource-drops/wave-ordinary-coin-weight
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/** Per-enemy card reward coefficients, before Wave Skip aggregation; never blanket coin/cell boosts. */
export interface CriticalCoinRewardInputs {
  /** Equipped Critical Coin probability, fraction; omitted is no card. */
  criticalCoinChance?: number
  /** Conditional chance to drop two instead of one, fraction; omitted is no mastery. */
  criticalCoinDoubleChance?: number
  /** Share of Basic kills eligible as critical damage; ownership does not establish this share. */
  criticalEligibleKillFraction?: number
}
export interface CellsCardRewardInputs {
  /** Flat cells per elite AFTER all other multipliers, including mastery. */
  cellsCardFlatBonus?: number
  /** Cells mastery multiplier before the flat card bonus; omitted is one. */
  cellsCardMasteryMultiplier?: number
}
function fraction(value: number, label: string): number {
  if (!Number.isFinite(value) || value < 0 || value > 1) throw new Error(`RESOURCE_CARD_FRACTION_INVALID:${label}`)
  return value
}

/**
 * Basic enemies normally drop zero. The card proc produces one coin, or two
 * conditionally with mastery. Only noncritical tower projectiles are excluded
 * from eligible damage; UW/orbs/Death Ray/thorns qualify in the community FAQ.
 * https://the-tower.notion.site/Guide-to-Improving-Coin-Income-1bf91383b93f80b883fefcd58298d20a
 * https://www.reddit.com/r/TheTowerGame/comments/1i3v1tu/ (2025-01-30: mastery Basic-only)
 */
export function criticalCoinExpectedBasePerBasicKill(input: CriticalCoinRewardInputs = {}): number {
  const chance = fraction(input.criticalCoinChance ?? 0, 'criticalCoinChance')
  const doubleChance = fraction(input.criticalCoinDoubleChance ?? 0, 'criticalCoinDoubleChance')
  const eligible = fraction(input.criticalEligibleKillFraction ?? 0, 'criticalEligibleKillFraction')
  return eligible * chance * (1 + doubleChance)
}

/**
 * v29 Cells card: multiplier first, then flat card amount LAST per elite kill.
 * No flat award on Fetch, ordinary kills, or per-wave payout. Expected rewards
 * are combined by the caller only after this per-kill expression.
 * https://www.reddit.com/r/TheTowerGame/comments/1vznnki/ (2026-08-27 v29 card text)
 */
export function cellsPerEliteAfterCard(baseAfterOtherMultipliers: number, input: CellsCardRewardInputs = {}): number {
  const flat = input.cellsCardFlatBonus ?? 0, mastery = input.cellsCardMasteryMultiplier ?? 1
  if (![baseAfterOtherMultipliers, flat, mastery].every(Number.isFinite)
    || baseAfterOtherMultipliers < 0 || flat < 0 || mastery < 1) throw new Error('RESOURCE_CELLS_CARD_INPUT_INVALID')
  const result = baseAfterOtherMultipliers * mastery + flat
  if (!Number.isFinite(result)) throw new Error('RESOURCE_CELLS_CARD_OVERFLOW')
  return result
}
